sys.path.insert(0, "/repo")

# Import the specific module
from comfy_extras.nodes_string import StringContains

def test_string_contains_with_none():
    """Test that StringContains crashes with None input in case-insensitive mode."""
    node = StringContains()

    # Test case: case_sensitive=False (which triggers .lower() calls)
    # This should crash with AttributeError: 'NoneType' object has no attribute 'lower'
    try:
        result = node.execute(None, "test", False)
        print("No exception raised with None inputs")
        return False  # Bug not manifested
    except AttributeError as e:
        if "'NoneType' object has no attribute 'lower'" in str(e):
            print(f"CRASH DETECTED: {e}")
            return True  # Bug manifested
        else:
            raise
    except Exception as e:
        print(f"Different exception: {e}")
        return False

if __name__ == "__main__":
    try:
        bug_manifested = test_string_contains_with_none()
        if bug_manifested:
            print("STATUS: CRASHED | ExceptionType: AttributeError: 'NoneType' object has no attribute 'lower'")
            sys.exit(1)
        else:
            print("STATUS: SAFE")
            sys.exit(0)
    except Exception as e:
        print(f"STATUS: CRASHED | ExceptionType: {type(e).__name__}: {e}")
        sys.exit(1)
